/*
 * Renders the voice catalogue and plays the samples.
 *
 * The catalogue itself is in voices.js, generated by tools/build-voices.py from the script
 * that rendered the wavs — so the line printed on a card is the line you hear. Nothing here
 * talks to the TTS server; these are pre-rendered files under samples/.
 */

(function () {
  "use strict";

  var catalogue = window.VOICE_CATALOGUE || [];

  /* Tags the sample lines with the language they are actually in, so a browser picks a font
     that can draw them and a screen reader does not read Japanese as English. Keyed by the
     first letter of the voice id, the same way Kokoro names them. */
  var LANG_TAGS = {
    a: "en-US",
    b: "en-GB",
    e: "es",
    f: "fr",
    i: "it",
    p: "pt-BR",
    h: "hi",
    j: "ja",
    z: "zh-CN"
  };

  var ICON_PLAY = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M8 5.5v13l11-6.5z" fill="currentColor"/></svg>';
  var ICON_STOP = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><rect x="7" y="7" width="10" height="10" rx="2" fill="currentColor"/></svg>';

  var catalogueEl = document.getElementById("catalogue");

  /* One audio element for the whole page: starting a second sample has to stop the first,
     and a single element gets that for free. */
  var audio = new Audio();
  audio.preload = "none";
  var playingCard = null;
  var cards = [];

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text != null) node.textContent = text;
    return node;
  }

  function buildCard(voice, langTag) {
    var card = el("article", "card");
    card.dataset.id = voice.id;

    var play = el("button", "play");
    play.type = "button";
    play.innerHTML = ICON_PLAY;
    play.setAttribute("aria-label", "Play the " + voice.name + " sample");
    play.addEventListener("click", function () {
      toggle(card, voice);
    });

    var body = el("div", "card-body");
    var head = el("div", "card-head");
    head.appendChild(el("span", "voice-name", voice.name));

    var id = el("button", "voice-id", voice.id);
    id.type = "button";
    id.dataset.id = voice.id;
    id.title = "Copy [" + voice.id + "]";
    id.setAttribute("aria-label", "Copy " + voice.id + " as a chat prefix");
    id.addEventListener("click", function () {
      copyPrefix(id, voice.id);
    });
    head.appendChild(id);
    body.appendChild(head);

    var line = el("p", "line", voice.line);
    line.lang = langTag;
    body.appendChild(line);

    if (voice.translation) {
      body.appendChild(el("p", "translation", voice.translation));
    }

    card.appendChild(play);
    card.appendChild(body);
    card.appendChild(el("span", "progress"));

    cards.push(card);
    return card;
  }

  function render() {
    var fragment = document.createDocumentFragment();

    catalogue.forEach(function (group) {
      var section = el("section", "country");
      var head = el("div", "country-head");
      head.appendChild(el("span", "flag", group.flag));
      head.appendChild(el("h2", null, group.country));
      head.appendChild(el("span", "tag tag-accent", group.language));
      head.appendChild(el("span", "tag tag-neutral", group.voices.length + " voices"));
      section.appendChild(head);

      /* Female first, then male — the ids sort that way too (af_ before am_). */
      ["Female", "Male"].forEach(function (gender) {
        var voices = group.voices.filter(function (v) {
          return v.gender === gender;
        });
        if (!voices.length) return;

        var block = el("div", "gender");
        block.appendChild(el("h3", "gender-label", gender));

        var grid = el("div", "grid");
        voices.forEach(function (voice) {
          grid.appendChild(buildCard(voice, LANG_TAGS[voice.id.charAt(0)] || "en"));
        });
        block.appendChild(grid);
        section.appendChild(block);
      });

      fragment.appendChild(section);
    });

    catalogueEl.appendChild(fragment);
  }

  /* — playback — */

  function stop() {
    audio.pause();
    if (!playingCard) return;
    playingCard.classList.remove("is-playing");
    playingCard.querySelector(".play").innerHTML = ICON_PLAY;
    playingCard.querySelector(".progress").style.width = "0";
    playingCard = null;
  }

  function toggle(card, voice) {
    var wasPlaying = playingCard === card;
    stop();
    if (wasPlaying) return;

    // Assigning src reloads from the start, so there is no currentTime to reset.
    audio.src = "samples/" + voice.id + ".wav";
    playingCard = card;
    card.classList.add("is-playing");
    card.querySelector(".play").innerHTML = ICON_STOP;

    var started = audio.play();
    if (started && started.catch) {
      started.catch(function () {
        // Autoplay policy or a missing file: drop straight back to the idle state rather
        // than leaving a card stuck showing a stop button.
        stop();
      });
    }
  }

  audio.addEventListener("timeupdate", function () {
    if (!playingCard || !audio.duration) return;
    var pct = (audio.currentTime / audio.duration) * 100;
    playingCard.querySelector(".progress").style.width = pct + "%";
  });
  audio.addEventListener("ended", stop);
  audio.addEventListener("error", stop);

  /* — copy — */

  var copyResetTimer = null;
  var copiedButton = null;

  function resetCopied() {
    clearTimeout(copyResetTimer);
    if (!copiedButton) return;
    copiedButton.classList.remove("is-copied");
    copiedButton.textContent = copiedButton.dataset.id;
    copiedButton = null;
  }

  function copyPrefix(button, id) {
    var text = "[" + id + "] ";
    var done = function () {
      // Clicking a second id before the first has reverted would otherwise leave that
      // first button reading "copied" forever — only one timer exists.
      resetCopied();
      copiedButton = button;
      button.classList.add("is-copied");
      button.textContent = "copied";
      copyResetTimer = setTimeout(resetCopied, 1100);
    };

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, function () {
        legacyCopy(text, done);
      });
    } else {
      // Clipboard API needs a secure context; over plain http on the LAN it is absent.
      legacyCopy(text, done);
    }
  }

  function legacyCopy(text, done) {
    var scratch = document.createElement("textarea");
    scratch.value = text;
    scratch.setAttribute("readonly", "");
    scratch.style.position = "fixed";
    scratch.style.opacity = "0";
    document.body.appendChild(scratch);
    scratch.select();
    try {
      if (document.execCommand("copy")) done();
    } catch (err) {
      /* Nothing sensible left to try; the id is on screen to be typed. */
    }
    document.body.removeChild(scratch);
  }

  /*
   * The list goes up first, before anything optional is wired.
   *
   * Cloudflare caches this script but not the page that loads it, so a browser can pair new
   * markup with an older app.js. When it does, whatever the old script expects to find and
   * cannot becomes an exception — and anything after it never runs. Building the catalogue
   * before touching a single optional element means the worst such a mismatch can cost is a
   * key binding or the footer count, never the page's whole reason for existing.
   *
   * tools/stamp-assets.py exists to keep that pairing from happening at all; this is what
   * makes the failure survivable if it ever does.
   */
  render();

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") stop();
  });

  var totalEl = document.getElementById("total");
  if (totalEl) totalEl.textContent = cards.length + " " + totalEl.textContent;
})();
